parts.text:
{
  "extractions": [
    {
      "unit": "F002",
      "unit_attributes": {
        "modality_explanation": "The prohibition 'No person may operate... unless' establishes an operating prohibition unless the specified condition is met.",
        "statement": "No person may operate a civil aircraft of U.S. registry at cabin pressure altitudes above 12,500 feet (MSL) up to and including 14,000 feet (MSL) unless the required minimum flight crew is provided with and uses supplemental oxygen for that part of the flight at those altitudes that is of more than 30 minutes duration.",
        "kind": "prohibition",
        "modality": "must_not",
        "scope_quotes": ["F001"]
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "modality_explanation": "Phrased as 'No person may operate... unless', creating a prohibition against operating without meeting the condition.",
        "statement": "No person may operate a civil aircraft of U.S. registry at cabin pressure altitudes above 14,000 feet (MSL) unless the required minimum flight crew is provided with and uses supplemental oxygen during the entire flight time at those altitudes.",
        "kind": "prohibition",
        "modality": "must_not",
        "scope_quotes": ["F001"]
      }
    },
    {
      "unit": "F004",
      "unit_attributes": {
        "modality_explanation": "Phrased as 'No person may operate... unless', creating a prohibition against operation unless the supplemental oxygen condition is met.",
        "statement": "No person may operate a civil aircraft of U.S. registry at cabin pressure altitudes above 15,000 feet (MSL) unless each occupant of the aircraft is provided with supplemental oxygen.",
        "kind": "prohibition",
        "modality": "must_not",
        "scope_quotes": ["F001"]
      }
    },
    {
      "unit": "F006",
      "unit_attributes": {
        "modality_explanation": "Phrased as 'No person may operate... unless', prohibiting operation of a pressurized cabin civil aircraft of U.S. registry without the specified 10-minute supplemental oxygen supply.",
        "statement": "No person may operate a civil aircraft of U.S. registry with a pressurized cabin at flight altitudes above flight level 250 unless at least a 10-minute supply of supplemental oxygen, in addition to any oxygen required to satisfy 14 CFR § 91.211(a), is available for each occupant of the aircraft for use in the event that a descent is necessitated by loss of cabin pressurization.",
        "kind": "prohibition",
        "modality": "must_not",
        "scope_quotes": ["F005"],
        "references": ["paragraph (a) of this section"]
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "modality_explanation": "Formulated as 'No person may operate... unless', establishing a prohibition on operating above FL 350 unless one pilot wears and uses the specified oxygen mask, subject to an exception.",
        "statement": "No person may operate a civil aircraft of U.S. registry with a pressurized cabin at flight altitudes above flight level 350 unless one pilot at the controls of the airplane is wearing and using an oxygen mask that is secured and sealed and that either supplies oxygen at all times or automatically supplies oxygen whenever the cabin pressure altitude of the airplane exceeds 14,000 feet (MSL), except that the one pilot need not wear and use an oxygen mask while at or below flight level 410 if there are two pilots at the controls and each pilot has a quick-donning type of oxygen mask that can be placed on the face with one hand from the ready position within 5 seconds, supplying oxygen and properly secured and sealed.",
        "kind": "prohibition",
        "modality": "must_not",
        "scope_quotes": ["F005"]
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "modality_explanation": "The text 'need not wear and use' directly specifies an exemption from the requirement to wear and use an oxygen mask under the stated conditions.",
        "statement": "When operating a civil aircraft of U.S. registry with a pressurized cabin at or below flight level 410, the one pilot at the controls need not wear and use an oxygen mask if there are two pilots at the controls and each pilot has a quick-donning type of oxygen mask that can be placed on the face with one hand from the ready position within 5 seconds, supplying oxygen and properly secured and sealed.",
        "kind": "exemption",
        "modality": "not_required",
        "scope_quotes": ["F005"]
      }
    },
    {
      "unit": "F008",
      "unit_attributes": {
        "modality_explanation": "The word 'shall' indicates a mandatory duty for the remaining pilot at the controls.",
        "statement": "Notwithstanding 14 CFR § 91.211(b)(1)(ii), if for any reason at any time it is necessary for one pilot to leave the controls of the aircraft when operating at flight altitudes above flight level 350, the remaining pilot at the controls shall put on and use an oxygen mask until the other pilot has returned to that crewmember's station.",
        "kind": "requirement",
        "modality": "must",
        "references": ["paragraph (b)(1)(ii) of this section"]
      }
    }
  ]
}
